  const flag = eq === -1 ? arg : arg.slice(0, eq);
  const resolved = resolveLongOption(flag);

  if (resolved === '--help') {
    process.stdout.write(`${helpText(prog)}\n`);
    process.exit(0);
  }

  const dest = resolved === null ? null : resolved.slice(2);
  if (dest === null || !DESTS.includes(dest)) {
    extras.push(arg);
    continue;
  }

  if (eq !== -1) {
    values[dest] = arg.slice(eq + 1);
  } else {
    const next = argv[i + 1];
    if (next === undefined || looksLikeOptional(next)) {
      fail(prog, `argument --${dest}: expected one argument`);
    }
    values[dest] = next;
    i++;
  }
} else {
  extras.push(arg);
}
